#!/usr/bin/env python3
"""
forge_weather_7day_20261004.py

Replaces the Richmond Weather card's single current-conditions line with a
7-day forecast: high/low, conditions, chance of rain, wind speed and
direction, one block per day, today first.

WHAT IT TOUCHES: forge_actions.py only. Nothing else is read or written
except the backup it makes first.

HOW IT IS SAFE:
  * refuses to run unless forge_actions.py matches the expected pre-image
    SHA-256 exactly, so it cannot land on an unexpected version
  * writes a timestamped backup BEFORE touching anything
  * verifies the post-image SHA-256 after writing, and restores the backup
    if it does not match
  * ast.parse on the result before it is accepted
  * running it twice is harmless: the second run sees the new SHA, reports
    "already applied", and changes nothing

AFTER RUNNING: forge_actions.py is the generator, so the brief does not
change until you commit, push, and run the workflow.
"""
import ast
import base64
import gzip
import hashlib
import os
import shutil
import sys
import time

TARGET = "forge_actions.py"
PRE_SHA = "4a814d5966f98edb5b6f9e4f9b05dd3cc076e591788707babe3b48b786b4b0cd"
POST_SHA = "c96b1069d8cacef5aeb28f3b572e27f4b5911ce490ac896ab683287f8ec35b4d"
PAYLOAD = ""


def sha(b):
    return hashlib.sha256(b).hexdigest()


def fail(msg):
    print("ABORTED: " + msg)
    print("Nothing was changed.")
    sys.exit(1)


def main():
    if not os.path.exists(TARGET):
        fail(TARGET + " not found. Run this from inside the repo folder, "
             "the one holding forge_actions.py.")

    current = open(TARGET, "rb").read()
    got = sha(current)

    if got == POST_SHA:
        print("Already applied - " + TARGET + " is already the 7-day version.")
        print("Nothing to do.")
        return

    if got != PRE_SHA:
        fail("unexpected " + TARGET + ".\n"
             "  expected pre-image: " + PRE_SHA + "\n"
             "  found             : " + got + "\n"
             "Run  git pull --rebase  first. If it still differs, the file has "
             "local edits and this installer must be rebuilt against it.")

    new = gzip.decompress(base64.b64decode(PAYLOAD))
    if sha(new) != POST_SHA:
        fail("embedded payload is corrupt (post-image SHA mismatch). "
             "The file was probably truncated in transit - re-download it.")

    try:
        ast.parse(new.decode("utf-8"))
    except SyntaxError as e:
        fail("embedded payload does not parse as Python: " + str(e))

    backup = TARGET + ".bak-weather7day-" + time.strftime("%Y%m%d-%H%M%S")
    shutil.copy2(TARGET, backup)
    print("Backup written: " + backup)

    with open(TARGET, "wb") as f:
        f.write(new)

    check = open(TARGET, "rb").read()
    if sha(check) != POST_SHA:
        shutil.copy2(backup, TARGET)
        fail("post-write verification failed. The backup has been restored.")

    text = check.decode("utf-8")
    problems = []
    if text.count("def get_weather") != 1:
        problems.append("get_weather is not defined exactly once")
    if text.count("def render_weather_card") != 1:
        problems.append("render_weather_card is not defined exactly once")
    if "{weather_html}" not in text:
        problems.append("the card template slot is missing")
    if "{weather}" in text:
        problems.append("the old {weather} slot is still present")
    if "weather_html = render_weather_card(weather)" not in text:
        problems.append("the renderer is never called")
    if "forecast_days=7" not in text:
        problems.append("the 7-day request parameter is missing")
    if len(problems) > 0:
        shutil.copy2(backup, TARGET)
        fail("post-conditions failed (backup restored): " + "; ".join(problems))

    print("")
    print("OK - " + TARGET + " is now the 7-day forecast version.")
    print("  post-image SHA-256: " + POST_SHA)
    print("")
    print("The brief itself has NOT changed yet. forge_actions.py is the")
    print("generator: commit, push, then run the workflow.")


if __name__ == "__main__":
    main()
